package com.mo.economy_system.common.transfer;
import com.mo.economy_system.common.check.*;import com.mo.economy_system.common.network.EconomyNetworkLimits;import java.util.*;
/** Session-scoped target cache populated only after a protocol-24 send succeeds. */
public final class CheckedFileTransferManifestCache{public record Key(UUID requesterId,ClientFileCheckType type,String fileName){public Key{Objects.requireNonNull(requesterId);Objects.requireNonNull(type);fileName=CheckedFileTransferValidation.fileName(fileName);}}public record Entry(long size,String sha256,long expiresAtNanos){public Entry{if(size<0||size>EconomyNetworkLimits.MAX_TRANSFER_FILE_BYTES)throw new IllegalArgumentException("size");sha256=CheckedFileTransferValidation.sha256(sha256);}}private final int capacity;private final LinkedHashMap<Key,Entry> entries=new LinkedHashMap<>();public CheckedFileTransferManifestCache(){this(EconomyNetworkLimits.MAX_CHECK_FILES);}public CheckedFileTransferManifestCache(int c){capacity=c;}
 public synchronized void replace(UUID requester,ClientFileCheckResult result,long now){entries.keySet().removeIf(k->k.requesterId().equals(requester)&&k.type()==result.checkType());if(result.status()!=ClientFileCheckStatus.SUCCESS&&result.status()!=ClientFileCheckStatus.TRUNCATED)return;long expiry=now+300_000_000_000L;for(ClientFileCheckEntry e:result.files()){if(entries.size()>=capacity)break;if(e.size()<=EconomyNetworkLimits.MAX_TRANSFER_FILE_BYTES)entries.put(new Key(requester,result.checkType(),e.fileName()),new Entry(e.size(),e.sha256(),expiry));}}
 public synchronized Optional<Entry> find(Key key,long now){entries.entrySet().removeIf(e->now>=e.getValue().expiresAtNanos());return Optional.ofNullable(entries.get(key));}public synchronized void clear(){entries.clear();}}
